tools.example:
pr_verify -full_check -file pr_verify.rpt ./impl/config_add_routed.dcp ./impl/config_mul_routed.dcp
# multiple
pr_verify -initial ./impl/config_add_routed.dcp -additional {./impl/config_mul_routed.dcp ./impl/config_blank_routed.dcp}

create_macro sync_pair
update_macro sync_pair {u_sync/meta_reg X0Y0 u_sync/sync_reg X0Y0}
set_property BEL AFF [get_cells u_sync/meta_reg]
set_property BEL BFF [get_cells u_sync/sync_reg]
# RTL alternative
(* RLOC = "X0Y0" *) FDRE meta (...); (* RLOC = "X0Y0" *) FDRE sync (...);

proc check_async_reg_names {} {
  foreach c [get_cells -hier -filter {ASYNC_REG == 1}] {
    if {![string match *sync* [get_property NAME $c]]} {
      create_drc_violation -name MYCO-1 -msg "ASYNC_REG cell $c not named *sync*" $c
    }
  }
}
create_drc_check -name MYCO-1 -hiername MyCompany -desc "Synchronizer naming" -severity Warning -rule_body check_async_reg_names
create_drc_ruledeck myco_rules
add_drc_checks -ruledeck myco_rules MYCO-1 TIMING-* PLHOLDVIO-*
report_drc -ruledecks myco_rules -file myco_drc.rpt

foreach cs {constrs_1 constrs_2} {
  copy_run -name impl_$cs [get_runs impl_1]
  set_property constrset $cs [get_runs impl_$cs]
}
launch_runs impl_constrs_1 impl_constrs_2 -jobs 8
wait_on_run impl_constrs_2
foreach r [get_runs impl_constrs*] { puts "$r WNS=[get_property STATS.WNS $r]" }
delete_runs [get_runs impl_constrs_2]

# Find unsafe crossings and the cells involved
report_cdc -details -severity Critical
foreach v [get_cdc_violations -filter {CHECK == CDC-1 || CHECK == CDC-4}] {
  puts "[get_property CHECK $v]: [get_property DESCRIPTION $v]"
}

# Find nets crossing SLRs after placement
set xslr {}
foreach n [get_nets -hier -filter {FLAT_PIN_COUNT > 1 && TYPE == SIGNAL}] {
  if {[llength [lsort -unique [get_slrs -of_objects [get_cells -of_objects $n]]]] > 1} { lappend xslr $n }
}
puts "[llength $xslr] SLR-crossing nets"
